"use strict";

/**
 * Sum an array of { amount: "<string>", currency: "<string>" } rows
 * into a single Number, rounded to 2 decimal places (half-up at the cent).
 *
 * Bad / missing / empty amounts contribute 0 (never NaN).
 * Leading currency symbols (e.g. "$") and whitespace are stripped; sign is
 * honoured.
 */
function sumAmounts(rows) {
  if (!Array.isArray(rows)) return 0;

  var total = 0;

  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row || typeof row.amount !== "string") continue;

    // Strip whitespace and leading currency symbols ($, €, £, ¥)
    var raw = row.amount.trim().replace(/^[$€£¥]\s*/, "");

    // Skip empty / unparseable
    if (raw === "") continue;

    var n = Number(raw);
    if (isNaN(n)) continue;

    total += n;
  }

  // Half-up rounding to 2 decimal places
  return Math.round(total * 100) / 100;
}

module.exports = { sumAmounts: sumAmounts };

